{"implementation":"def solve(case):
    import sys
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    n = len(nodes)
    # Build a quick lookup dict for distances
    dist_map = {}
    for a, b, d in dist_list:
        key = (a, b) if a < b else (b, a)
        dist_map[key] = d
    edges = []
    for i in range(n):
        u = nodes[i]
        cu = core[u]
        for j in range(i+1, n):
            v = nodes[j]
            cv = core[v]
            pair = (u, v) if u < v else (v, u)
            d = dist_map[pair]
            w = max(cu, cv, d)
            edges.append((w, u, v))
    # Sort by weight, then first endpoint, then second endpoint
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {}
    rank = {}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    for node in nodes:
        parent[node] = node
        rank[node] = 0
    mst = []
    total = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst.append([u, v, w])
            total += w
            if len(mst) == n - 1:
                break
    if len(mst) != n - 1:
        raise ValueError('Graph is not connected')
    return {'mst_edges': mst, 'total_weight': total}"}
